import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"Spec conformance","description":"","frontmatter":{},"headers":[],"relativePath":"policies/spec-conformance.md","filePath":"policies/spec-conformance.md","lastUpdated":1793726242000}'),r={name:"policies/spec-conformance.md"};function n(i,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="spec-conformance" tabindex="-1">Spec conformance <a class="header-anchor" href="#spec-conformance" aria-label="Permalink to &quot;Spec conformance&quot;">​</a></h1><p>kernl conforms to specifications it does not own. This page says which ones, what &quot;upstream first&quot; means in practice, and how a gap is recorded.</p><h2 id="authority" tabindex="-1">Authority <a class="header-anchor" href="#authority" aria-label="Permalink to &quot;Authority&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Authority</th><th>Local copy</th></tr></thead><tbody><tr><td>Shell–applet protocol</td><td>NIP-5D, <a href="https://github.com/nostr-protocol/nips/pull/2303" target="_blank" rel="noreferrer">nostr-protocol/nips PR #2303</a></td><td>none</td></tr><tr><td>NAP domains (<code>relay</code>, <code>outbox</code>, <code>dm</code>, <code>resource</code>, …)</td><td><a href="https://github.com/napplet/naps" target="_blank" rel="noreferrer">napplet/naps</a></td><td>none</td></tr><tr><td>Wire types and dispatch</td><td><a href="https://www.npmjs.com/package/@napplet/core" target="_blank" rel="noreferrer"><code>@napplet/core</code></a>, pinned <code>&gt;=0.37.0 &lt;0.38.0</code></td><td>the installed package</td></tr><tr><td>Shell composition</td><td>kehto source, <code>@kehto/*</code> at the pinned ranges</td><td>the installed packages</td></tr><tr><td>Event layer</td><td>applesauce v7, <a href="https://applesauce.build" target="_blank" rel="noreferrer">applesauce.build</a></td><td>the installed packages</td></tr><tr><td>Messaging protocols</td><td>NIP-17, NIP-04, the nostr double-ratchet draft, as named in each provider&#39;s <code>specification</code></td><td>none</td></tr></tbody></table><p>kernl keeps no local copy of a specification text. A copy drifts; a link does not. When the PR or a NAP document changes, the behaviour changes in kernl in a pull request that cites the clause.</p><h2 id="upstream-first" tabindex="-1">Upstream first <a class="header-anchor" href="#upstream-first" aria-label="Permalink to &quot;Upstream first&quot;">​</a></h2><p>When kernl needs something a specification or an upstream package does not provide, the order is:</p><ol><li><strong>Compose it from what exists.</strong> Most of kernl is this: the guard composes <code>@kehto/firewall</code>&#39;s <code>evaluate()</code>, the restrictive posture composes <code>resolveEnvironment</code> and <code>aclState.grant</code>.</li><li><strong>Propose it upstream.</strong> An issue or pull request on <code>kehto/web</code>, <code>napplet/naps</code> or <code>nostr-protocol/nips</code>, as appropriate. The four kehto gaps kernl has found, still to be filed upstream, are listed in <a href="./../alpha-status#upstream-gaps">Alpha status</a>.</li><li><strong>Implement it locally with a recorded gap.</strong> Only when 1 is impossible and 2 is pending. The local implementation sits behind an interface, cites the upstream issue, and is removed when upstream lands.</li></ol><p>kernl never re-implements a kehto primitive because it was easier than reading kehto&#39;s source, and never invents wire format. When a NAP is ambiguous, kernl prefers an upstream issue over a guess and records the ambiguity next to the code.</p><h2 id="what-conformance-is-checked-by" tabindex="-1">What conformance is checked by <a class="header-anchor" href="#what-conformance-is-checked-by" aria-label="Permalink to &quot;What conformance is checked by&quot;">​</a></h2><ul><li><strong>Gherkin scenarios</strong> in <code>features/</code> for every protocol-visible behaviour, named after the clause they implement where one exists.</li><li><strong>Review.</strong> A change that touches an envelope shape, a domain&#39;s semantics or the handshake cites the clause in its description. A reviewer checks the clause, not the summary.</li></ul><p><code>@napplet/conformance</code> (envelope validators per NAP domain, manifest validation and the reference mock shell&#39;s expectations of a host) is not part of the test suite yet; running it against the shell&#39;s bridge is on the <a href="./../roadmap#_7-conformance">Roadmap</a>.</p><p>The docs are non-normative. Where a page here and the specification disagree, the specification wins and the page has a bug.</p><h2 id="recording-a-gap" tabindex="-1">Recording a gap <a class="header-anchor" href="#recording-a-gap" aria-label="Permalink to &quot;Recording a gap&quot;">​</a></h2><p>A gap is anything kernl does that the specification does not say, or does not do that the specification says. Record it in three places:</p><ol><li><strong>Next to the code</strong>, as a comment that names the clause and the upstream issue. This is one of the few comments the slop gate accepts, because a reader could not infer it.</li><li><strong>In <code>DECISIONS.md</code></strong>, as a <code>D-NNN</code> entry with Context, Decision, Consequences and Reversal cost. If the gap is a kehto seam, the entry says what upstream change would close it.</li><li><strong>In <a href="./../alpha-status">Alpha status</a></strong>, under upstream gaps, so a reader deciding whether to depend on kernl sees it without reading the decisions log.</li></ol><p>A gap closes when upstream lands and the local layer is deleted. The <code>DECISIONS.md</code> entry stays, with a <code>Superseded by</code> line.</p><h2 id="tie-breaking" tabindex="-1">Tie-breaking <a class="header-anchor" href="#tie-breaking" aria-label="Permalink to &quot;Tie-breaking&quot;">​</a></h2><p>Protocol conformance is second in <code>SOUL.md</code>&#39;s tie-breakers, below the user&#39;s safety and agency and above the applet developer&#39;s ability to build. A conformance requirement that would weaken the user&#39;s position is not implemented silently; it is raised upstream with the conflict stated, and <code>DECISIONS.md</code> records which way kernl went while the question is open.</p>',19)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
